-- Confidence score upgrades
UPDATE geo_entities SET confidence_score = 0.85 WHERE id IN (1012, 882, 905, 774, 1026, 751, 752, 769, 795, 826);

COMMIT;

SELECT g.id, g.name_original, g.confidence_score, (SELECT count(*) FROM sources s WHERE s.entity_id=g.id) AS n_src FROM geo_entities g WHERE g.id IN (751, 752, 769, 774, 795, 826, 882, 905, 1012, 1026) ORDER BY g.id;
